head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.LastJob = "조회";
// 화면 리사이징

// 번역지원 화면 회사 추가 팝업

scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gRdoMktId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_jongmok_OnLoadCompleted
 * @description dts_jongmok 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            panel_page.show("");
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        } else {
            panel_page.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.dts_jongmok_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        // Grd_com_isur.style.display ="";
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.img_search_onclick" });
    }
};

/**
 * @method
 * @name img_add_onclick
 * @description 「추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_add_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.img_add_onclick" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnClick
 * @description grd_jongmok 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnClick = async function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === "DELETE_YN") {
            if (confirm("정말 삭제하시겠습니까?")) {
                await scwin.delete(row);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.grd_jongmok_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 실패하였습니다.");
        // alert_error(trs_Save);
        txb_com_abbrv.setValue("");
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 완료되었습니다.");
        txb_com_abbrv.setValue("");
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSFT19000_POP.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.ListIsurcdSearch(txb_isur_cd, txb_com_abbrv, scwin.gLdMktTp, "Y");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF19000_POP.xml", SCREN_PROCS_TP_CD_02);
        $c.data.downloadGridViewOffice(grd_jongmok, "영문번역대상법인 목록", "영문번역대상법인 목록" + ".xlsx", "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSFT19000_POP.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Save.insertRow();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&LD_MKT_TP=" + rdo_MKT_ID.getValue();
    url += "&ISUR_CD=";
    url += "&SCREN_ID=" + "ULDSTF19000_POP.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/DsclSearchAll.do",
        ref : "",
        target : "dts_jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_isur_cd.getValue().length !== 5) {
        await $c.win.alert("회사 코드 5자리를 입력해주세요");
        txb_isur_cd.focus();
        return;
    }
    if (txb_com_abbrv.getValue().length <= 0) {
        await $c.win.alert("회사명을 입력해주세요");
        txb_com_abbrv.focus();
        return;
    }
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        if (dts_jongmok.getCellData(i, "ISUR_CD") === txb_isur_cd.getValue()) {
            await $c.win.alert("이미 등록된 법인입니다.");
            return;
        }

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

    }
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    scwin.LastJob = "저장"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/DsclSearchAll.do",
        ref : "dts_Save",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name delete
 * @description ********************************************************************
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    dts_Save.setCellData(1, "DEL_ISUR_CD", dts_jongmok.getCellData(row, "ISUR_CD"));
    dts_Save.setCellData(1, "LD_MKT_TP_CD", rdo_MKT_ID.getValue());
    dts_Save.setCellData(1, "EMP_NO", js_emp_no);
    scwin.LastJob = "삭제"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/DsclSearchAll.do",
        ref : "dts_Save",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        rdo_MKT_ID.setValue(js_market);
        rdo_MKT_ID.setDisabled(true);
        // showObj(panel_mkt, false);
        // showObj(img_search,false);

    } else {
        scwin.gRdoMktId = $c.frame.path("../").scwin.gRdoMktId;
        rdo_MKT_ID.setValue(scwin.gRdoMktId);
        rdo_MKT_ID.setDisabled(false);
        // showObj(img_search,true);

        scwin.gLdMktTp = rdo_MKT_ID.getValue();
    }
    await scwin.setHeader();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    // gComAbbrv = dts_jongmok.NameString(eval(obj),"COM_ABBRV");
    gIsurCd = dts_jongmok.getCellData(Number(obj), "ISUR_CD");
};
